package br.com.onda;
import android.content.*;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;import com.tom_roush.pdfbox.pdmodel.PDDocument;import com.tom_roush.pdfbox.io.MemoryUsageSetting;import com.tom_roush.pdfbox.text.PDFTextStripper;
@androidx.media3.common.util.UnstableApi
final class MemoryIndexer {
 interface Control {void check()throws IOException;void progress(String stage,long at,long total);}
 static int index(Context c,MemoryStore.Source source,Control control)throws Exception{try(MemoryStore store=new MemoryStore(c)){return store.replace(source,writer->{control.check();if("pdf".equals(source.kind))pdf(c,Uri.parse(source.uri),writer,control);else if(source.kind.startsWith("subtitle")){String text=read(c,Uri.parse(source.sidecar),4*1024*1024,control);java.util.List<MemoryText.Cue> cues=MemoryText.subtitles(text);int at=0;for(MemoryText.Cue cue:cues){control.check();writer.add(cue);control.progress("Indexando legenda",++at,cues.size());}}else MemoryAudio.scan(c,Uri.parse(source.uri),writer,control);control.check();if(!source.stamp.equals(AudioChapterStore.stamp(c,Uri.parse(source.uri))))throw new IOException("O arquivo mudou durante a análise. Tente novamente.");});}}
 static String read(Context c,Uri uri,int max,Control control)throws IOException{try(InputStream in=c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Arquivo indisponível");byte[] block=new byte[16384];int n;while((n=in.read(block))!=-1){control.check();if(out.size()>max-n)throw new IOException("Legenda muito grande para esta leitura (4 MB).");out.write(block,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
 static void pdf(Context c,Uri uri,MemoryStore.Writer writer,Control control)throws Exception{File copy=File.createTempFile("memory-pdf-",".pdf",c.getCacheDir());try{try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(copy)){if(in==null)throw new IOException("PDF indisponível");byte[] block=new byte[32768];long size=0;int n;while((n=in.read(block))!=-1){control.check();size+=n;if(size>PdfBook.MAX_BYTES)throw new IOException("Este leitor aceita PDFs de até 64 MB.");out.write(block,0,n);}}PDFBoxResourceLoader.init(c.getApplicationContext());try(PDDocument doc=PDDocument.load(copy,MemoryUsageSetting.setupTempFileOnly().setTempDir(c.getCacheDir()))){if(doc.getNumberOfPages()>PdfBook.MAX_PAGES)throw new IOException("PDF com mais de 5.000 páginas.");if(!doc.getCurrentAccessPermission().canExtractContent())throw new IOException("O PDF não permite extrair texto.");PDFTextStripper stripper=new PDFTextStripper();stripper.setSortByPosition(true);for(int page=0;page<doc.getNumberOfPages();page++){control.check();stripper.setStartPage(page+1);stripper.setEndPage(page+1);StringBuilder text=new StringBuilder();Writer sink=new Writer(){public void write(char[] a,int off,int count)throws IOException{control.check();if(text.length()+count>100000)throw new IOException("Página com texto demais para indexar com segurança.");text.append(a,off,count);}public void flush(){}public void close(){}};stripper.writeText(doc,sink);for(String part:MemoryText.chunks(text.toString()))writer.add(new MemoryText.Cue(0,0,page,part));control.progress("Lendo PDF • página "+(page+1),page+1,doc.getNumberOfPages());}}}finally{copy.delete();}}
}
